insert into recrutement.groupes (id,categorie,nom,description,description_longue,couleur,icone,ordre) values ($s$guide$s$,$s$pole$s$,$s$Pôle Guide$s$,$s$Vos compagnons de route, de votre première minute sur le serveur à la validation de votre premier personnage.$s$,$s$Les Staffs Guides sont vos compagnons de route, de votre toute première minute sur le serveur jusqu'à la création et la validation de votre premier personnage. Toujours à votre écoute, ils répondent à vos questions, étudient vos suggestions, gèrent vos tickets et corrigent vos fiches avec bienveillance. Ce sont également eux qui insufflent de la vie et de la joie dans la communauté en organisant toutes les animations Hors-RP du serveur.$s$,$s$#5A9A70$s$,$s$boussole$s$,1) on conflict (id) do nothing;
insert into recrutement.groupes (id,categorie,nom,description,description_longue,couleur,icone,ordre) values ($s$narration$s$,$s$pole$s$,$s$Pôle Narration$s$,$s$Maîtres d'œuvre de votre expérience de jeu : grands événements, PNJ et intrigues personnelles.$s$,$s$Ces staffs sont les maîtres d'œuvre de votre expérience de jeu ! De la création des grands événements narratifs à la gestion rigoureuse des PNJs, en passant par l'aide personnalisée en ticket pour développer vos propres intrigues, ils sont les gardiens de la cohérence et de l'évolution de tout l'univers des Clans.$s$,$s$#8A9A42$s$,$s$plume$s$,2) on conflict (id) do nothing;
insert into recrutement.groupes (id,categorie,nom,description,description_longue,couleur,icone,ordre) values ($s$tonnerre$s$,$s$clan$s$,$s$Clan du Tonnerre$s$,$s$$s$,$s$$s$,$s$#6aa07a$s$,$s$eclair$s$,1) on conflict (id) do nothing;
