insert into recrutement.postes (categorie,groupe,nom,description,missions,anciennete,disponibilite,note_candidat,statut,places_total,places_dispo,questions,options,ouvert_le,ordre) values ('staff',$s$guide$s$,$s$Staff Guide$s$,$s$Aider, accompagner et animer : le visage du serveur pour les membres.$s$,array[$s$Aider et accompagner les membres$s$,$s$Créer des animations$s$,$s$Lire et accepter les questionnaires d'entrée$s$,$s$Gérer les conflits et les tickets$s$]::text[],$s$1 à 2 mois sur le serveur$s$,$s$5h / semaine minimum$s$,$s$Les options sont facultatives : tu peux candidater au rôle sans en choisir.$s$,'ouvert',3,3,$j$[{"id":"q1","label":"Comment accueillerais-tu un nouveau membre perdu ?","type":"textarea","min":30,"required":true},{"id":"q2","label":"Comment gères-tu un ticket urgent quand tu es occupé·e ?","type":"textarea","min":30,"required":true},{"id":"q3","label":"Deux membres s'opposent dans un salon et la tension monte. Comment gères-tu ce conflit ?","type":"textarea","min":30,"required":true},{"id":"q4","label":"Un questionnaire d'entrée est incomplet ou limite. Comment décides-tu, et que réponds-tu au candidat ?","type":"textarea","min":30,"required":true},{"id":"q5","label":"Propose une idée d’animation pour le serveur.","type":"textarea","min":30,"required":true}]$j$::jsonb,$j$[{"id":"regisseur","nom":"Régisseur·se de fiche","description":"Correction des fiches de personnage.","questions":[{"id":"q1","label":"Comment vérifies-tu la cohérence d'une fiche avec les règles du serveur ?","type":"textarea","min":30,"required":true},{"id":"q2","label":"Comment formules-tu un retour de correction sans décourager le membre ?","type":"textarea","min":30,"required":true},{"id":"q3","label":"Un membre conteste ta correction — comment réagis-tu ?","type":"textarea","min":30,"required":true}]},{"id":"geneticien","nom":"Généticien·ne","description":"Correction génétique des personnages.","questions":[{"id":"q1","label":"Explique le fonctionnement de l'hérédité de la couleur des yeux dans le Codex.","type":"textarea","min":30,"required":true},{"id":"q2","label":"Un membre demande un pelage rare pour son OC — comment évalues-tu la demande ?","type":"textarea","min":30,"required":true},{"id":"q3","label":"Comment tiens-tu un registre génétique à jour sur un serveur actif ?","type":"textarea","min":30,"required":true}]}]$j$::jsonb,now(),1);
insert into recrutement.postes (categorie,groupe,nom,description,missions,anciennete,disponibilite,note_candidat,statut,places_total,places_dispo,questions,options,ouvert_le,ordre) values ('staff',$s$narration$s$,$s$Staff Narration$s$,$s$Faire vivre le roleplay : tickets, événements et cohérence narrative.$s$,array[$s$Aider les membres en ticket pour le RP$s$,$s$Créer des événements role-play$s$,$s$S'assurer que les règles role-play sont appliquées$s$,$s$Créer des tâches dans le clan$s$]::text[],$s$1 à 2 mois sur le serveur$s$,$s$5h / semaine minimum$s$,$s$Les options sont facultatives : tu peux candidater au rôle sans en choisir.$s$,'ouvert',2,2,$j$[{"id":"q1","label":"Un membre vient en ticket avec une intrigue complexe — comment l'accompagnes-tu ?","type":"textarea","min":30,"required":true},{"id":"q2","label":"Un membre enfreint une règle RP en pleine scène — comment interviens-tu sans casser l’immersion ?","type":"textarea","min":30,"required":true},{"id":"q3","label":"Propose une idée d’événement role-play pour le serveur.","type":"textarea","min":30,"required":true},{"id":"q4","label":"Quelles tâches imagines-tu pour dynamiser la vie d’un clan ?","type":"textarea","min":30,"required":true}]$j$::jsonb,$j$[{"id":"pnj","nom":"Gestion PNJ","description":"Gestion et incarnation des PNJ de l'univers.","questions":[{"id":"q1","label":"Comment gères-tu un PNJ impliqué dans plusieurs fils narratifs actifs ?","type":"textarea","min":30,"required":true},{"id":"q2","label":"Crée un concept de PNJ secondaire pour le Clan de l'Ombre.","type":"textarea","min":30,"required":true},{"id":"q3","label":"Un PNJ que tu joues doit prendre une décision qui déplaira à certains membres — comment procèdes-tu ?","type":"textarea","min":30,"required":true}]}]$j$::jsonb,now(),2);
insert into recrutement.postes (categorie,groupe,nom,type_rang,titulaire,note,statut,places_total,places_dispo,questions,ouvert_le,ordre) values ('hr',$s$tonnerre$s$,$s$Meneur·se Étoile$s$,$s$meneur$s$,$s$Étoile de Framboisier$s$,null,$s$indispo$s$,1,0,$j$[{"id":"q1","label":"Un clan allié demande refuge sur ton territoire après une catastrophe. Certains guerriers s'y opposent. Comment gères-tu cette situation ?","type":"textarea","min":30,"required":true},{"id":"q2","label":"Tu dois prendre une décision vitale pour ton clan en l'absence de ton lieutenant·e. Comment procèdes-tu ?","type":"textarea","min":30,"required":true},{"id":"q3","label":"Ton clan traverse une période de faible activité. Comment maintiens-tu la cohésion et motives-tu tes membres ?","type":"textarea","min":30,"required":true}]$j$::jsonb,null,1);
