insert into recrutement.formulaires (type,titre,description,ouvert,etapes) values ($s$staff$s$,$s$Candidature Staff$s$,$s$Rejoins l'équipe qui fait vivre le serveur : Staff Guide ou Staff Narration.$s$,true,$j$[{"id":"toi","titre":"Toi","description":"Faisons connaissance.","champs":[{"id":"pseudo","label":"Ton pseudo Discord","type":"text","required":true,"hint":"Celui qu'on retrouve sur le serveur.","placeholder":"ex : araxia"},{"id":"anciennete","label":"Depuis combien de temps es-tu sur le serveur ?","type":"choice","required":true,"options":["Moins d'un mois","1 à 2 mois","3 à 6 mois","Plus de 6 mois","Plus d'un an"]},{"id":"presentation","label":"Présente-toi","type":"textarea","min":150,"required":true,"hint":"Qui es-tu, hors et en RP ? Ce qui te définit en quelques lignes."}]},{"id":"role","titre":"Ton rôle","description":"Choisis ton équipe, puis les options qui t’intéressent.","kind":"poste","max":2},{"id":"dispos","titre":"Disponibilités","description":"Pour bien t'intégrer à l'équipe.","champs":[{"id":"heures","label":"Combien d'heures par semaine peux-tu consacrer au staff ?","type":"choice","required":true,"options":["Moins de 3h","3 à 5h","5 à 8h","Plus de 8h"]},{"id":"dispos","label":"Tes disponibilités habituelles","type":"textarea","min":20,"required":true,"hint":"Jours, créneaux, périodes plus chargées (examens, vacances…)."},{"id":"experience","label":"Expérience associative ou communautaire","type":"textarea","required":false,"hint":"Staff sur un autre serveur, association, modération… (facultatif)"}]},{"id":"motivation","titre":"Motivation","description":"","champs":[{"id":"plaisir","label":"Qu'est-ce qui te plaît dans le serveur ?","type":"textarea","min":100,"required":true},{"id":"apport","label":"Qu'aimerais-tu apporter à l'équipe ?","type":"textarea","min":50,"required":false}]},{"id":"situations","titre":"Mises en situation","description":"Réponds comme tu le ferais vraiment.","kind":"questions_poste"}]$j$::jsonb) on conflict (type) do nothing;
insert into recrutement.formulaires (type,titre,description,ouvert,etapes) values ($s$hr$s$,$s$Candidature Haut Rang$s$,$s$Mène, seconde ou soigne : candidate à un rang de ton clan.$s$,true,$j$[{"id":"perso","titre":"Ton personnage","description":"Le personnage qui porterait le rang.","champs":[{"id":"pseudo","label":"Ton pseudo Discord","type":"text","required":true,"hint":"Celui qu'on retrouve sur le serveur.","placeholder":"ex : araxia"},{"id":"oc_nom","label":"Nom de l'OC candidat·e","type":"text","required":true},{"id":"oc_rang","label":"Son rang actuel dans le clan","type":"text","required":true,"placeholder":"ex : Guerrier·ère, Apprenti·e…"},{"id":"anciennete","label":"Depuis combien de temps es-tu sur le serveur ?","type":"choice","required":true,"options":["Moins d'un mois","1 à 2 mois","3 à 6 mois","Plus de 6 mois","Plus d'un an"]},{"id":"oc_anciennete","label":"Ancienneté de l'OC","type":"text","required":true,"placeholder":"ex : 3 mois"},{"id":"frequence","label":"Fréquence de jeu avec cet OC","type":"choice","required":true,"options":["1 à 3 RP / semaine","4 à 7 RP / semaine","8 à 14 RP / semaine","Plus de 14 RP / semaine"]},{"id":"scenes","label":"Liens vers 2-3 scènes RP représentatives","type":"url_list","required":true,"hint":"Un lien par ligne (liens Discord de messages ou de fils)."}]},{"id":"rang","titre":"Le rang visé","description":"Seuls les rangs ouverts sont proposés.","kind":"poste","max":1},{"id":"situations","titre":"Mises en situation","description":"Place-toi dans la peau du rang.","kind":"questions_poste"},{"id":"rp","titre":"Section RP","description":"Montre-nous ta plume.","champs":[{"id":"motivation","label":"Motivation IC : pourquoi cet OC veut ce rang ?","type":"textarea","min":150,"required":true},{"id":"extrait","label":"Extrait roleplay libre","type":"textarea","min":200,"required":true,"hint":"Une scène courte qui illustre ton OC dans ce rôle."}]}]$j$::jsonb) on conflict (type) do nothing;
insert into recrutement.formulaires (type,titre,description,ouvert,etapes) values ($s$oc3$s$,$s$3ème OC$s$,$s$Un troisième personnage pour enrichir ton aventure.$s$,true,$j$[{"id":"toi","titre":"Toi","description":"","champs":[{"id":"pseudo","label":"Ton pseudo Discord","type":"text","required":true,"hint":"Celui qu'on retrouve sur le serveur.","placeholder":"ex : araxia"},{"id":"anciennete","label":"Depuis combien de temps es-tu sur le serveur ?","type":"choice","required":true,"options":["Moins d'un mois","1 à 2 mois","3 à 6 mois","Plus de 6 mois","Plus d'un an"]},{"id":"ocs_actuels","label":"Tes OCs actuels et ta fréquence de jeu avec chacun","type":"textarea","min":20,"required":true},{"id":"activite","label":"Ton activité RP globale","type":"choice","required":true,"options":["1 à 3 RP / semaine","4 à 7 RP / semaine","8 à 14 RP / semaine","Plus de 14 RP / semaine"]}]},{"id":"nouveau","titre":"Le nouvel OC","description":"Présente-nous ton futur personnage.","champs":[{"id":"clan","label":"Clan visé","type":"choice","required":true,"options":["Clan du Tonnerre","Clan du Vent","Clan de l'Ombre"]},{"id":"nom_oc","label":"Nom envisagé","type":"text","required":true},{"id":"concept","label":"Concept et personnalité","type":"textarea","min":120,"required":true}]},{"id":"motivation","titre":"Motivation","description":"","champs":[{"id":"pourquoi","label":"Pourquoi souhaites-tu un OC supplémentaire ?","type":"textarea","min":100,"required":true}]}]$j$::jsonb) on conflict (type) do nothing;
insert into recrutement.formulaires (type,titre,description,ouvert,etapes) values ($s$oc4$s$,$s$4ème OC$s$,$s$Un quatrième personnage : pour les joueurs les plus actifs.$s$,true,$j$[{"id":"toi","titre":"Toi","description":"","champs":[{"id":"pseudo","label":"Ton pseudo Discord","type":"text","required":true,"hint":"Celui qu'on retrouve sur le serveur.","placeholder":"ex : araxia"},{"id":"anciennete","label":"Depuis combien de temps es-tu sur le serveur ?","type":"choice","required":true,"options":["Moins d'un mois","1 à 2 mois","3 à 6 mois","Plus de 6 mois","Plus d'un an"]},{"id":"ocs_actuels","label":"Tes OCs actuels et ta fréquence de jeu avec chacun","type":"textarea","min":20,"required":true},{"id":"activite","label":"Ton activité RP globale","type":"choice","required":true,"options":["1 à 3 RP / semaine","4 à 7 RP / semaine","8 à 14 RP / semaine","Plus de 14 RP / semaine"]}]},{"id":"nouveau","titre":"Le nouvel OC","description":"Présente-nous ton futur personnage.","champs":[{"id":"clan","label":"Clan visé","type":"choice","required":true,"options":["Clan du Tonnerre","Clan du Vent","Clan de l'Ombre"]},{"id":"nom_oc","label":"Nom envisagé","type":"text","required":true},{"id":"concept","label":"Concept et personnalité","type":"textarea","min":120,"required":true}]},{"id":"motivation","titre":"Motivation","description":"","champs":[{"id":"pourquoi","label":"Pourquoi souhaites-tu un OC supplémentaire ?","type":"textarea","min":100,"required":true},{"id":"extrait","label":"Extrait roleplay avec cet OC ou dans le style prévu","type":"textarea","min":200,"required":true}]}]$j$::jsonb) on conflict (type) do nothing;
insert into recrutement.faq (section,question,reponse,ordre) values ($s$Processus général$s$,$s$Quel est le délai de réponse ?$s$,$s$Le staff étudie les candidatures dès que possible, généralement sous une à deux semaines. Tu peux suivre l'avancement à tout moment avec ton code de suivi ou en te connectant avec Discord.$s$,0);
insert into recrutement.faq (section,question,reponse,ordre) values ($s$Processus général$s$,$s$Puis-je postuler à plusieurs postes en même temps ?$s$,$s$Oui. Tu peux déposer une candidature Staff (jusqu'à deux rôles), une candidature Haut Rang et une demande d'OC supplémentaire en parallèle. Une seule candidature en cours par type est acceptée.$s$,1);
insert into recrutement.faq (section,question,reponse,ordre) values ($s$Processus général$s$,$s$Puis-je modifier ma candidature après l'envoi ?$s$,$s$Non, mais tu peux la retirer depuis la page « Mon suivi » (tant qu'elle n'est pas tranchée) et en déposer une nouvelle.$s$,2);
insert into recrutement.faq (section,question,reponse,ordre) values ($s$Processus général$s$,$s$J'ai perdu mon code de suivi, que faire ?$s$,$s$Connecte-toi avec Discord sur la page « Mon suivi » : toutes tes candidatures y apparaissent. Sinon, la recherche par pseudo retrouve ton code, sans jamais afficher le contenu de tes réponses.$s$,3);
insert into recrutement.faq (section,question,reponse,ordre) values ($s$Processus général$s$,$s$Où lire la réponse du staff ?$s$,$s$Sur la page « Mon suivi » : la décision (acceptée ou refusée) est accompagnée d'un message du staff que tu peux relire à tout moment. Tu es aussi mentionné·e sur Discord.$s$,4);
insert into recrutement.faq (section,question,reponse,ordre) values ($s$Candidatures Staff$s$,$s$Quelle ancienneté faut-il avoir ?$s$,$s$En général 1 à 2 mois sur le serveur. Le détail est indiqué dans la fiche de chaque rôle.$s$,5);
insert into recrutement.faq (section,question,reponse,ordre) values ($s$Candidatures Staff$s$,$s$Y a-t-il une période d'essai ?$s$,$s$Oui. Les nouveaux staffs sont accompagnés pendant une période d'essai avant d'être confirmés dans leur rôle.$s$,6);
insert into recrutement.faq (section,question,reponse,ordre) values ($s$Candidatures Staff$s$,$s$Les recrutements Staff sont-ils ouverts en permanence ?$s$,$s$Non : seuls les postes marqués « Ouvert » acceptent des candidatures. Si un poste est complet, inscris-toi sur sa liste d'attente.$s$,7);
insert into recrutement.faq (section,question,reponse,ordre) values ($s$Candidatures Staff$s$,$s$Que sont les options ?$s$,$s$Dans chaque équipe, des options facultatives existent (Régisseur·se de fiche et Généticien·ne chez les Guides, Gestion PNJ chez les Narrateurs). Elles ajoutent quelques questions, et tu es libre de ne pas en choisir.$s$,8);
insert into recrutement.faq (section,question,reponse,ordre) values ($s$Hauts Rangs$s$,$s$Quand les postes de Haut Rang ouvrent-ils ?$s$,$s$Quand un poste se libère. Il apparaît alors comme « Ouvert » sur la page Postes et sur la page Hauts Rangs.$s$,9);
insert into recrutement.faq (section,question,reponse,ordre) values ($s$Hauts Rangs$s$,$s$Dois-je appartenir au clan du poste visé ?$s$,$s$Ton OC candidat doit être membre du clan concerné et avoir une activité RP régulière.$s$,10);
insert into recrutement.faq (section,question,reponse,ordre) values ($s$Hauts Rangs$s$,$s$Comment fonctionne la liste d'attente ?$s$,$s$Inscris ton pseudo Discord sur la liste d'un poste indisponible : tu seras mentionné·e sur Discord à son ouverture.$s$,11);
insert into recrutement.faq (section,question,reponse,ordre) values ($s$OC supplémentaire$s$,$s$Quelle différence entre le 3ème et le 4ème OC ?$s$,$s$Le 4ème OC demande en plus un extrait roleplay, car il suppose une activité encore plus soutenue.$s$,12);
insert into recrutement.faq (section,question,reponse,ordre) values ($s$OC supplémentaire$s$,$s$Ma demande peut-elle être refusée malgré mon activité ?$s$,$s$Oui : le staff regarde aussi la cohérence du concept et l'équilibre entre tes OCs et celui des clans. Un refus est toujours accompagné d'une explication.$s$,13);
insert into recrutement.modeles (kind,titre,contenu,ordre) values ($s$acceptee$s$,$s$Bienvenue$s$,$s$Bienvenue dans l'équipe ! Ta candidature nous a convaincus. Nous te contactons sur Discord très bientôt pour la suite.$s$,0);
insert into recrutement.modeles (kind,titre,contenu,ordre) values ($s$acceptee$s$,$s$Période d'essai$s$,$s$Ta candidature est acceptée : tu commences par une période d'essai accompagnée. Un·e membre du staff te contactera très vite pour t'expliquer le fonctionnement.$s$,1);
insert into recrutement.modeles (kind,titre,contenu,ordre) values ($s$acceptee$s$,$s$OC validé$s$,$s$Ton nouvel OC est validé ! Tu peux créer sa fiche et le présenter à la régie. Bon jeu !$s$,2);
insert into recrutement.modeles (kind,titre,contenu,ordre) values ($s$refusee$s$,$s$Pas cette fois$s$,$s$Merci pour ta candidature et le temps passé dessus. Nous ne pouvons pas la retenir cette fois-ci, mais n'hésite pas à retenter dans quelques semaines.$s$,3);
insert into recrutement.modeles (kind,titre,contenu,ordre) values ($s$refusee$s$,$s$Manque d'ancienneté$s$,$s$Ta candidature est intéressante, mais nous aimerions que tu aies un peu plus d'ancienneté sur le serveur. Reviens vers nous bientôt !$s$,4);
insert into recrutement.modeles (kind,titre,contenu,ordre) values ($s$refusee$s$,$s$Poste pourvu$s$,$s$Merci de ta candidature. Le poste a finalement été pourvu ; nous gardons ton dossier en mémoire pour une prochaine ouverture.$s$,5);
insert into recrutement.modeles (kind,titre,contenu,ordre) values ($s$refusee$s$,$s$Activité insuffisante$s$,$s$Ta candidature n'a pas été retenue car ton activité RP actuelle ne nous permet pas de valider cette demande. Reviens quand ton rythme aura évolué !$s$,6);
insert into recrutement.modeles (kind,titre,contenu,ordre) values ($s$examen$s$,$s$Dossier en lecture$s$,$s$Ton dossier est en cours de lecture par l'équipe. Nous revenons vers toi dès qu'une décision est prise.$s$,7);
