insert into recrutement.parametres (cle,valeur) values ($s$annonce$s$,$j$""$j$::jsonb) on conflict (cle) do nothing;
insert into recrutement.parametres (cle,valeur) values ($s$delai_reponse$s$,$j$"une à deux semaines"$j$::jsonb) on conflict (cle) do nothing;
